sp_page.css:
 section.page {
  background-color: #D9EBE6 !important;
}
section.page, main.body, div.body {
  padding-top: 5px !important;
  padding-bottom: 5px !important;
}

.container-fluid {
    padding-left: 0;
    padding-right: 0;
}

  /* Fit the logo inside the existing header */
.navbar-brand img {
  max-height: 55px !important;
  width: auto !important;
}

.navbar-brand {
  height: 70px !important;
  display: flex;
  align-items: center; 
}

/* Mobile & Tablet Specific Spacing */
@media (max-width: 767px) {
	.sp-column,
  	.iconlink {
      margin-bottom: 15px !important;
  }

/* Add spacing below pink description text container */
.padder-v {
  margin-bottom: 20px !important;
  }

/* Add breathing room for widgets at the bottom */
.sp-widget {
	margin-bottom: 20px !important;
  }
}
